import {readFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {resolve} from 'node:path';

function validateRules(rules) {
  if (!Array.isArray(rules)) {
    throw new Error('rules must be an array');
  }

  const validated = new Array(rules.length);
  const ids = new Set();

  for (let index = 0; index < rules.length; index += 1) {
    if (!Object.prototype.hasOwnProperty.call(rules, index)) {
      throw new Error('rules must be a dense array');
    }

    const rule = rules[index];
    if (rule === null || typeof rule !== 'object' || Array.isArray(rule)) {
      throw new Error(`rule at index ${index} must be a non-null, non-array object`);
    }

    const {id, literal, replacement} = rule;
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error(`rule at index ${index} must have a nonempty string id`);
    }
    if (ids.has(id)) {
      throw new Error(`rule id ${JSON.stringify(id)} is not unique`);
    }
    if (typeof literal !== 'string' || literal.length === 0) {
      throw new Error(`rule at index ${index} must have a nonempty string literal`);
    }
    if (typeof replacement !== 'string') {
      throw new Error(`rule at index ${index} must have a string replacement`);
    }

    ids.add(id);
    validated[index] = {id, literal, replacement, index};
  }

  return validated;
}

export function planRedactions(text, rules) {
  if (typeof text !== 'string') {
    throw new Error('text must be a string');
  }

  // Validation is deliberately completed before examining the text.
  const validatedRules = validateRules(rules);
  const edits = [];
  const resultParts = [];
  let sourcePosition = 0;

  while (sourcePosition < text.length) {
    let selected;

    for (const rule of validatedRules) {
      if (!text.startsWith(rule.literal, sourcePosition)) {
        continue;
      }
      if (
        selected === undefined ||
        rule.literal.length > selected.literal.length ||
        (rule.literal.length === selected.literal.length && rule.index < selected.index)
      ) {
        selected = rule;
      }
    }

    if (selected === undefined) {
      resultParts.push(text[sourcePosition]);
      sourcePosition += 1;
      continue;
    }

    const end = sourcePosition + selected.literal.length;
    edits.push({start: sourcePosition, end, id: selected.id});
    resultParts.push(selected.replacement);
    sourcePosition = end;
  }

  const redactedText = resultParts.join('');
  return {
    text: redactedText,
    edits,
    originalBytes: Buffer.byteLength(text, 'utf8'),
    redactedBytes: Buffer.byteLength(redactedText, 'utf8'),
  };
}

function runCli() {
  try {
    if (process.argv.length !== 3) {
      throw new Error('usage: node redaction-plan.js INPUT_JSON_FILE');
    }

    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    if (input === null || typeof input !== 'object' || Array.isArray(input)) {
      throw new Error('input JSON must be a non-null, non-array object');
    }

    const result = planRedactions(input.text, input.rules);
    process.stdout.write(`${JSON.stringify(result)}\n`);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`redaction-plan: ${message || 'unknown error'}\n`);
    process.exitCode = 2;
  }
}

const isDirectExecution =
  process.argv[1] !== undefined && fileURLToPath(import.meta.url) === resolve(process.argv[1]);

if (isDirectExecution) {
  runCli();
}

